function tile(x){const desc=categoryNotes[x.id]?.[locale]||"";return `<a class="category-tile" ${href(x.id==='actualizaciones'?'/noticias':'/explorar/'+x.id)}><span class="category-art" style="background-image:url('${categoryArtHQ[x.id]}'),url('${categoryArt[x.id]}')" aria-hidden="true"></span><span class="category-info"><b>${esc(tr(x.label))}</b><small>${esc(desc)}</small></span><span class="arrow" aria-hidden="true">↗</span></a>`}
function communityArtwork(i,cl){
 // Original generic illustration, visibly labeled. It does not depict evidence of the report.
 const id=String(i.id||'');
 const kind=/domains?/.test(id)?'domains':/devkit|development/.test(id)?'development':/video|footage/.test(id)?'footage':/animation/.test(id)?'animation':'report';
 const labels={
  es:{domains:['🌐','Rumor sobre dominios','Ilustración genérica'],development:['⚙','Rumor sobre desarrollo','Ilustración genérica'],footage:['▶','Video no confirmado','Ilustración genérica'],animation:['◇','Rumor sobre animaciones','Ilustración genérica'],report:['✦','Rumor de la comunidad','Ilustración genérica']},
  en:{domains:['🌐','Domain rumour','Generic illustration'],development:['⚙','Development rumour','Generic illustration'],footage:['▶','Unconfirmed video','Generic illustration'],animation:['◇','Animation rumour','Generic illustration'],report:['✦','Community rumour','Generic illustration']},
  pt:{domains:['🌐','Rumor sobre domínios','Ilustração genérica'],development:['⚙','Rumor sobre desenvolvimento','Ilustração genérica'],footage:['▶','Vídeo não confirmado','Ilustração genérica'],animation:['◇','Rumor sobre animações','Ilustração genérica'],report:['✦','Rumor da comunidade','Ilustração genérica']}
 };
 const [icon,label,note]=(labels[locale]||labels.es)[kind];
 return '<span class="'+esc(cl)+' vi-community-art vi-community-art-'+kind+'" role="img" aria-label="'+esc(label+' — '+note)+'"><span class="vi-community-art-icon" aria-hidden="true">'+esc(icon)+'</span><span class="vi-community-art-caption"><strong>'+esc(label)+'</strong><small>'+esc(note)+'</small></span></span>';
}
function thumb(i,cl='thumb'){if(i.facets?.community===1&&!i.image)return communityArtwork(i,cl);const fallback=categoryArt[i.category]||'./assets/original/scene.svg';const officialPhoto=typeof i.image?.remote==='string'&&/^https:\/\/media-rockstargames-com\.akamaized\.net\/tina-uploads\/posts\/[a-z0-9]+\/[a-f0-9]{40}\.(?:jpg|jpeg|png|webp)$/.test(i.image.remote)?i.image.remote:null;const provided=typeof i.image?.data==='string'&&i.image.data.startsWith('blob:')?i.image.data:(officialPhoto||(typeof i.image?.path==='string'&&i.image.path.startsWith('./assets/original/')?i.image.path:fallback));return `<img class="${cl}" src="${esc(provided)}" data-vi-image-fallback="${esc(fallback)}" alt="${esc(tr(i.title))}" loading="lazy" referrerpolicy="no-referrer">`;}
function fave(i,small=true){const yes=store('fav').includes(i.id);return `<button type="button" class="quick-fav ${yes?'is-fav':''}" data-toggle="fav" data-id="${esc(i.id)}" aria-pressed="${yes}" aria-label="${yes?'Quitar de favoritos':'Marcar como favorito'}: ${esc(tr(i.title))}" title="${yes?'Quitar de favoritos':'Marcar como favorito'}">${yes?'★':'☆'}</button>`}
function newsStatusLabel(i){return i.facets?.community===1?(locale==='en'?'UNCONFIRMED':locale==='pt'?'NÃO CONFIRMADO':'NO CONFIRMADO'):i.status==='verified'?(locale==='en'?'VERIFIED':locale==='pt'?'VERIFICADO':'VERIFICADO'):'DEMO'}
function card(i,compareMode=false){return `<article class="content-card ${trackable(i)?'has-quick':''}${compareMode?' vi-compare-ready':''}"><a class="content-card-link" ${href('/ficha/'+i.id)}>${thumb(i)}<span class="content-text"><span class="overline">${esc(tr(cat(i.category).label))}</span><h3>${esc(tr(i.title))}</h3><p>${esc(tr(i.desc))}</p></span><span class="pill ${i.facets?.community===1?'pill-warning':i.status==='verified'?'pill-official':'pill-warning'}">${newsStatusLabel(i)}</span><span class="arrow">↗</span></a><span class="card-inline-actions">${quickProgress(i)}${fave(i)}${window.viDetailEnhancements?.comparePickButton(i,locale,compareMode===true?'pick':'open')||''}</span></article>`}
function resultCard(i){return `<article class="search-result">${thumb(i,'search-thumb')}<a class="search-result-link" ${href('/ficha/'+i.id)}><span><b>${esc(tr(i.title))}</b><small>${esc(tr(cat(i.category).label))} · ${newsStatusLabel(i)}</small></span><span class="arrow">↗</span></a><span class="card-inline-actions">${quickProgress(i)}${fave(i)}</span></article>`}

// V1.0: No hard-coded totals. The catalog is rebuilt from independent JSON records.
const progressGroups=[
 {id:'misiones',category:'misiones',title:'Misiones',verb:'completadas',color:'#f4a35a'},
 {id:'vehiculos',category:'vehiculos',title:'Vehículos',verb:'descubiertos',color:'#55b2ff'},
 {id:'armas',category:'armas',title:'Armas',verb:'registradas',color:'#e5b064'},
 {id:'economia',category:'economia',title:'Propiedades y negocios',verb:'adquiridos',color:'#ad90fa'},
 {id:'mapa-lugares',category:'mapa-lugares',title:'Lugares',verb:'visitados',color:'#50e5d2'},
 {id:'coleccionables',category:'coleccionables',title:'Coleccionables',verb:'encontrados',color:'#ed84c3'},
 {id:'personajes',category:'personajes',title:'Personajes',verb:'conocidos',color:'#73dca3'},
 {id:'actividades',category:'actividades',title:'Actividades',verb:'realizadas',color:'#f47b7b'}
];
function trackable(i){return i.status==='verified' && i.trackable!==false && i.recordType!=='story_overview' && progressGroups.some(g=>g.category===i.category)}
function tracked(catId){return records.filter(x=>x.category===catId && trackable(x))}
function checked(id){return store('done').includes(id)}
function quickProgress(i){if(!trackable(i))return '';const done=checked(i.id);const text=locale==='en'?(done?'↶ Mark missing':'✓ Mark owned'):locale==='pt'?(done?'↶ Desmarcar':'✓ Marcar'):( {vehiculos:['✓ Ya lo tengo','↶ No lo tengo'],armas:['✓ Ya la tengo','↶ No la tengo'],misiones:['✓ Completada','↶ Pendiente'],economia:['✓ Adquirido','↶ No adquirido'],'mapa-lugares':['✓ Visitado','↶ No visitado'],coleccionables:['✓ Encontrado','↶ No encontrado'],personajes:['✓ Conocido','↶ No conocido'],actividades:['✓ Realizada','↶ Pendiente']}[i.category]||['✓ Marcar','↶ Desmarcar'])[Number(done)];return `<button type="button" class="quick-complete ${done?'is-complete':''}" data-toggle="done" data-id="${esc(i.id)}" title="${esc(itemStatusLabel(i))}" aria-label="${esc(text+': '+tr(i.title))}" aria-pressed="${done}">${esc(text)}</button>`;}
function progressInfo(g){const all=tracked(g.category),marked=all.filter(x=>checked(x.id));return {...g,total:all.length,completed:marked.length,pending:all.filter(x=>!checked(x.id))}}
function itemStatusLabel(i){const labels={vehiculos:['No descubierto','Descubierto'],armas:['No registrada','Registrada'],misiones:['Pendiente','Completada'],economia:['No adquirido','Adquirido'], 'mapa-lugares':['No visitado','Visitado'],coleccionables:['No encontrado','Encontrado'],personajes:['No conocido','Conocido'],actividades:['Pendiente','Realizada']};return (labels[i.category]||['Pendiente','Completada'])[Number(checked(i.id))]}
const progressMarks={misiones:'✦',vehiculos:'▰',armas:'✚',economia:'⌂','mapa-lugares':'⌖',coleccionables:'◇',personajes:'◉',actividades:'⚑'};
function homeProgressPulse(){const labels=locale==='en'?['TOTAL','Registered','Pending','Favorites']:locale==='pt'?['TOTAL','Registrados','Pendentes','Favoritos']:['GLOBAL','Registrados','Pendientes','Favoritos'];const groups=progressGroups.map(progressInfo),total=groups.reduce((a,g)=>a+g.total,0),completed=groups.reduce((a,g)=>a+g.completed,0),percent=total?Math.round(completed*100/total):0;return `<div class="v113-home-pulse" aria-label="Progreso general ${completed} de ${total}"><div class="v113-pulse-ring" style="--pulse:${percent}%"><div><strong>${percent}%</strong><span>${labels[0]}</span></div></div><div class="v113-pulse-stats"><span><b>${completed}<small> / ${total}</small></b>${labels[1]}</span><span><b>${total-completed}</b>${labels[2]}</span><span><b>${store('fav').length}</b>${labels[3]}</span></div></div>`}
function progressPanel(compact=false,withLink=true){const groups=progressGroups.map(progressInfo);const shown=compact?['vehiculos','armas','mapa-lugares','personajes'].map(id=>groups.find(g=>g.category===id)).filter(Boolean):groups;return `<div class="progress-dashboard v113-progress v114-progress ${compact?'compact':''}">${shown.map(g=>{const ratio=g.total?Math.round(g.completed/g.total*100):0;return `<a class="progress-tile" style="--progress-color:${g.color};--progress-image:url('${categoryArt[g.category]}')" ${href('/explorar/'+g.category)} aria-label="${esc(g.title)} ${g.completed} de ${g.total}; ver todos"><div class="progress-top"><b><span class="progress-category-mark" aria-hidden="true">${progressMarks[g.category]||'✧'}</span>${esc(g.title)}</b><span class="progress-number">${g.completed}<span class="muted">/${g.total}</span></span></div><div class="progress-details"><span class="progress-verb">${esc(g.verb)}</span><span class="progress-remaining">${g.total?(g.total-g.completed)+' pendientes':'Datos pendientes'}</span></div><div class="progress-meter-head"><span>AVANCE DE PARTIDA</span><b>${g.total?ratio+'%':'—'}</b></div><div class="progress-track" role="progressbar" aria-valuenow="${g.completed}" aria-valuemin="0" aria-valuemax="${g.total}" aria-label="${esc(g.title)}"><span style="width:${ratio}%"></span></div><span class="progress-cta">${g.total?'Ver todos ↗':'Explorar categoría ↗'}<span class="progress-percent">${g.total?ratio+'%':'SIN DATOS'}</span></span></a>`}).join('')}</div>${compact&&withLink?`<a class="vi-progress-see-all" ${href('/partida')}><span>${locale==='en'?'See all 8 categories and my progress':locale==='pt'?'Ver as 8 categorias e meu progresso':'Ver las 8 categorías y mi progreso'}</span><span aria-hidden="true">↗</span></a>`:''}`}
let playProgressSort='catalogo',playProgressView='filas';
const playProgressOrder=['mapa-lugares','vehiculos','misiones','armas','economia','coleccionables','personajes','actividades'];
function playthroughProgress(){const groups=progressGroups.map(progressInfo);const total=groups.reduce((a,g)=>a+g.total,0),done=groups.reduce((a,g)=>a+g.completed,0),left=total-done,percentage=total?Math.round(done/total*100):null,available=groups.filter(g=>g.total>0),completedGroups=available.filter(g=>g.completed===g.total).length,validFav=records.filter(x=>store('fav').includes(x.id)).length,nextTarget=completedGroups<available.length?completedGroups+1:null;
 const ordered=[...groups].sort((a,b)=>playProgressSort==='avance'?((b.total?b.completed/b.total:-1)-(a.total?a.completed/a.total:-1))||playProgressOrder.indexOf(a.category)-playProgressOrder.indexOf(b.category):playProgressSort==='pendientes'?(b.pending.length-a.pending.length)||playProgressOrder.indexOf(a.category)-playProgressOrder.indexOf(b.category):playProgressOrder.indexOf(a.category)-playProgressOrder.indexOf(b.category));
 return `<div class="v120-playthrough" data-source="central-catalog"><div class="v120-section-title"><h2><span>▥</span> Progreso por categoría</h2><span>Los totales se actualizan desde el catálogo</span></div><section class="v120-overview" aria-label="Progreso global"><div class="v120-overview-top"><div class="v120-ring" style="--ring-percent:${percentage??0}%"><div><strong>${percentage===null?'—':percentage+'%'}</strong><small>COMPLETADO</small></div></div><div class="v120-overview-numbers"><span class="v120-overline">PROGRESO GLOBAL</span><p>Tu avance en GTA VI</p><strong>${done} <small>/ ${total}</small></strong><span>elementos registrados</span><b>${left}</b><span>pendientes</span></div><div class="v120-category-overview"><span class="v120-overline">CATEGORÍAS</span><p>${completedGroups} de ${available.length} completadas${available.length<progressGroups.length?' · '+(progressGroups.length-available.length)+' sin datos':''}</p><div class="v120-category-dots">${groups.map(g=>`<span class="${g.total===0?'unknown':g.completed===g.total?'finished':''}" title="${esc(g.title)} ${g.completed}/${g.total}">${g.total===0?'·':g.completed===g.total?'✓':''}</span>`).join('')}</div><div class="v120-mini-track"><i style="width:${available.length?completedGroups/available.length*100:0}%"></i></div><small>${available.length?Math.round(completedGroups/available.length*100)+'% de categorías con datos':'Sin categorías completables todavía'}</small></div><button type="button" class="v120-next-milestone" data-play-scroll="categories" aria-label="Ver categorías para completar el siguiente hito"><span class="v120-trophy">🏆</span><b>SIGUIENTE HITO</b><p>${available.length?(nextTarget?'Completá '+nextTarget+' '+(nextTarget===1?'categoría':'categorías'):'¡Completaste las categorías disponibles!'):'Se activará al incorporar fichas verificadas'}</p><div class="v120-mini-track"><i style="width:${nextTarget?completedGroups/nextTarget*100:100}%"></i></div><small>${nextTarget?completedGroups+' / '+nextTarget:available.length?'✓':'—'}</small></button></div><div class="v120-overview-stats"><a class="v120-stat-card" ${href('/partida?estado=completados')} aria-label="Ver elementos completados"><span>✓</span><strong>${done}</strong><small>Completados</small></a><a class="v120-stat-card" ${href('/partida?estado=pendientes')} aria-label="Ver elementos pendientes"><span>◉</span><strong>${left}</strong><small>Pendientes</small></a><a class="v120-stat-card" ${href('/partida?estado=favoritos')} aria-label="Ver favoritos"><span>★</span><strong>${validFav}</strong><small>Favoritos</small></a><button type="button" class="v120-stat-card" data-play-scroll="categories" aria-label="Ir a las categorías para ver cuáles están completas"><strong>${completedGroups} / ${available.length}</strong><small>Categorías completas</small></button></div></section><div class="v120-list-heading" id="play-category-list"><h3><span>▦</span> Categorías</h3><div class="v120-list-tools"><label>Ordenar por <select id="playProgressSort"><option value="catalogo" ${playProgressSort==='catalogo'?'selected':''}>Orden del catálogo</option><option value="avance" ${playProgressSort==='avance'?'selected':''}>Progreso</option><option value="pendientes" ${playProgressSort==='pendientes'?'selected':''}>Más pendientes</option></select></label></div></div><div class="v120-progress-list">${ordered.map((g,i)=>{const ratio=g.total?Math.round(g.completed/g.total*100):null;return `<a class="v120-progress-row" ${href('/explorar/'+g.category)} style="--progress-color:${g.color};--progress-image:url('${categoryArt[g.category]}')" aria-label="${esc(g.title)} ${g.completed} de ${g.total}; ver categoría"><span class="v120-row-order">${String(i+1).padStart(2,'0')}</span><span class="v120-row-icon">${progressMarks[g.category]||'✧'}</span><span class="v120-row-body"><strong>${esc(g.title)}</strong><small>${g.completed} / ${g.total} ${esc(g.verb)}${g.total===0?' · sin fichas contabilizables':''}</small><span class="v120-row-bar"><i style="width:${ratio??0}%"></i></span></span><b class="v120-row-percent">${ratio===null?'—':ratio+'%'}</b><span class="v120-row-arrow">›</span></a>`}).join('')}</div></div>`;}
function categoryList(id,items){const filter=(location.hash.match(/[?&]estado=([a-z]+)/)||[])[1]||'todos';const tabs=[['todos','Todos'],['pendientes','Me faltan'],['completados','Registrados'],['favoritos','Favoritos']];const eligible=items.filter(trackable);const visible=filter==='pendientes'?eligible.filter(x=>!checked(x.id)):filter==='completados'?eligible.filter(x=>checked(x.id)):filter==='favoritos'?items.filter(x=>store('fav').includes(x.id)):items;const catHref=(f)=>'/explorar/'+id+(f==='todos'?'':'?estado='+f);return `<div class="category-progress-line">${eligible.filter(x=>checked(x.id)).length} / ${eligible.length} · seguimiento personal <small>${eligible.length===0?'— todavía no hay elementos individuales verificables':''}</small></div><div class="filter-tabs" role="group" aria-label="Filtrar contenido">${tabs.map(([f,label])=>`<a class="filter-tab ${filter===f?'is-selected':''}" ${href(catHref(f))}>${label}</a>`).join('')}</div>${visible.length?`<div class="item-stack">${visible.map(i=>card(i,true)).join('')}</div>`:`<div class="empty-state">${filter==='pendientes'&&eligible.length&&eligible.every(x=>checked(x.id))?'¡Ya registraste todos los elementos disponibles!':filter!=='todos'?'No hay elementos para mostrar con ese filtro.':'Aún no hay fichas verificadas para esta sección.'}<div class="actions"><a class="ghost-btn" ${href(catHref('todos'))}>Ver todos ↗</a></div></div>`}`}
