// Single deterministic recommendation engine for React and the autonomous demo.
// Inputs: verified catalog, stable anonymous local visitor ID, local calendar day, completed IDs, recently opened IDs.
// No user health/personal data, no AI, no remote call, no hardcoded recommendations.
function dailyRecommendations(items,visitorId,localDay,completed=[],recent=[],limit=3){
 const done=new Set(completed),seen=new Set(recent.slice(0,8));
 const pool=items.filter(x=>x.status==='verified'&&x.recordType!=='story_overview');
 function score(s){let h=2166136261;for(let i=0;i<s.length;i++){h^=s.charCodeAt(i);h=Math.imul(h,16777619)}return h>>>0}
 const ranked=pool.map(x=>({item:x,priority:(done.has(x.id)?2:seen.has(x.id)?1:0),hash:score(visitorId+'|'+localDay+'|'+x.id)})).sort((a,b)=>a.priority-b.priority||a.hash-b.hash||a.item.id.localeCompare(b.item.id));
 const result=[],cats=new Set();
 for(const x of ranked){if(result.length>=limit)break;if(!cats.has(x.item.category)){result.push(x.item);cats.add(x.item.category)}}
 for(const x of ranked){if(result.length>=limit)break;if(!result.some(i=>i.id===x.item.id))result.push(x.item)}
 return result;
}

/* DAILY_DISCOVERY_END */
function dailyVisitor(){try{let id=localStorage.getItem("gta6-assistant:v1:visitor");if(!id){id=(globalThis.crypto?.randomUUID?.()||String(Date.now())+String(Math.random()));localStorage.setItem("gta6-assistant:v1:visitor",id)}return id}catch{return "session"}}
function dailySelection(limit=3){const d=new Date();const day=[d.getFullYear(),String(d.getMonth()+1).padStart(2,"0"),String(d.getDate()).padStart(2,"0")].join("-");return dailyRecommendations(records,dailyVisitor(),day,store("done"),store("recent"),limit)}
// V174: page through a daily, deterministic set without navigating or rerendering Inicio.
// Keep only the current 1/2/3 cards in the DOM so image loading stays lightweight.
let discoveryPage=0,discoveryDay='',discoverySize=0;
function dailyDiscoveryPageSize(){const w=window.innerWidth||document.documentElement.clientWidth||1280;return w<=700?1:w<=1050?2:3}
function dailyDiscoveryModel(){
 const d=new Date(),day=[d.getFullYear(),String(d.getMonth()+1).padStart(2,'0'),String(d.getDate()).padStart(2,'0')].join('-');
 const size=dailyDiscoveryPageSize();
 if(discoveryDay!==day){discoveryDay=day;discoveryPage=0;discoverySize=size}
 else if(discoverySize!==size){discoveryPage=Math.floor(discoveryPage*Math.max(discoverySize,1)/size);discoverySize=size}
 const items=dailySelection(12),pages=Math.max(1,Math.ceil(items.length/size));
 discoveryPage=Math.min(discoveryPage,pages-1);
 return {items,size,pages,page:discoveryPage,visible:items.slice(discoveryPage*size,(discoveryPage+1)*size)};
}
function dailyDiscoveryControls(model){
 const labels=locale==='en'?{prev:'Previous recommendations',next:'Next recommendations',nav:'Browse recommendations'}:locale==='pt'?{prev:'Recomendações anteriores',next:'Próximas recomendações',nav:'Navegar pelas recomendações'}:{prev:'Recomendaciones anteriores',next:'Siguientes recomendaciones',nav:'Navegar recomendaciones'};
 return '<div class="vi-discovery-nav" role="group" aria-label="'+esc(labels.nav)+'">'
  +'<button type="button" data-vi-discover-step="-1" aria-label="'+esc(labels.prev)+'" aria-controls="vi-discovery-cards"'+(model.pages<=1?' disabled':'')+'>‹</button>'
  +'<span data-vi-discover-count aria-live="polite">'+(model.page+1)+' / '+model.pages+'</span>'
  +'<button type="button" data-vi-discover-step="1" aria-label="'+esc(labels.next)+'" aria-controls="vi-discovery-cards"'+(model.pages<=1?' disabled':'')+'>›</button>'
  +'</div>';
}
function dailyDiscoverySection(){
 const m=dailyDiscoveryModel();
 const title=locale==='en'?'Discover something today':locale==='pt'?'Para descobrir hoje':'Para descubrir hoy';
 const subtitle=locale==='en'?'Different recommendations each day, based on what you have yet to explore.':locale==='pt'?'Recomendações diferentes a cada dia, com base no que ainda falta descobrir.':'Recomendaciones distintas cada día, según lo que todavía te falta descubrir.';
 const catalog=locale==='en'?'View catalog':locale==='pt'?'Ver catálogo':'Ver catálogo';
 return '<section class="v18-catalog-zone vi-discovery-section v177-discovery-section"><div class="v18-block-header"><div class="vi-discovery-heading"><span class="v18-section-kicker">04 / '+(locale==='en'?'OPEN ARCHIVE':locale==='pt'?'ARQUIVO ABERTO':'ARCHIVO ABIERTO')+'</span><h2>'+title+'</h2><p>'+subtitle+'</p></div><div class="vi-discovery-head-actions">'+dailyDiscoveryControls(m)+'<a class="v18-outline-link vi-discovery-catalog" '+href('/explorar')+'>'+esc(catalog)+' <span aria-hidden="true">↗</span></a></div></div><div class="item-stack" id="vi-discovery-cards">'+m.visible.map(i=>card(i)).join('')+'</div></section>';
}
function refreshDailyDiscovery(){
 const zone=document.querySelector('.home-v18 .vi-discovery-section');
 if(!zone)return;
 const stack=zone.querySelector('#vi-discovery-cards');if(!stack)return;
 const resized=discoverySize!==dailyDiscoveryPageSize();
 if(resized)stack.style.minHeight='';
 const m=dailyDiscoveryModel(),oldY=window.scrollY;
 const height=stack.getBoundingClientRect().height;
 if(!resized&&height>0)stack.style.minHeight=Math.max(height,parseFloat(stack.style.minHeight)||0)+'px';
 stack.innerHTML=m.visible.map(i=>card(i)).join('');
 const counter=zone.querySelector('[data-vi-discover-count]');
 if(counter)counter.textContent=(m.page+1)+' / '+m.pages;
 zone.querySelectorAll('[data-vi-discover-step]').forEach(btn=>btn.disabled=m.pages<=1);
 if(window.scrollY!==oldY)window.scrollTo({top:oldY,behavior:'instant'});
}
document.addEventListener('click',e=>{
 const btn=e.target.closest?.('[data-vi-discover-step]');if(!btn)return;
 e.preventDefault();
 const m=dailyDiscoveryModel();if(m.pages<=1)return;
 discoveryPage=(m.page+Number(btn.dataset.viDiscoverStep)+m.pages)%m.pages;
 refreshDailyDiscovery();
});
window.addEventListener('resize',()=>{
 if(document.querySelector('.home-v18 .vi-discovery-section')&&discoverySize!==dailyDiscoveryPageSize())refreshDailyDiscovery();
});
function homeYoutubeSection(){const art=['actualizaciones','personajes','vehiculos','mapa-lugares'];const channels=(homeYoutube[locale]||[]).map((c,i)=>`<a class="youtube-tile ${i===0?'youtube-official':''}" href="${esc(c.url)}" target="_blank" rel="noopener noreferrer"><span class="youtube-tile-art" style="background-image:linear-gradient(0deg,#0e1421dd,transparent 90%),url('${categoryArt[art[i%4]]}')"><span class="youtube-tile-play">▶</span></span><span class="youtube-tile-body"><span class="youtube-tile-tag">${esc(c.tag)}</span><b>${esc(c.name)}<span class="youtube-link-arrow">↗</span></b><small>${esc(c.description)}</small></span></a>`).join('');return `<section class="youtube-home v18-youtube v113-community"><div class="v18-block-header"><div><span class="v18-section-kicker">▶ COMMUNITY / VIDEO</span><h2>${locale==='es'?'La comunidad habla de GTA':locale==='pt'?'A comunidade fala de GTA':'The GTA community'}</h2><p>${locale==='es'?'Canales seleccionados por idioma. Solo Rockstar es fuente oficial.':locale==='pt'?'Canais selecionados por idioma. Só Rockstar é oficial.':'Channels by language; only Rockstar is official.'}</p></div><span class="v113-community-side">CANAL OFICIAL + CREADORES</span></div><div class="youtube-grid">${channels}</div></section>`}

// V1.11: carrusel permanente de Inicio, separado del Newswire dinámico.
function renderPermanentHero(){const i=Math.min(homeSlide,homePermanentConfig.length-1);return `<section class="home-permanent" aria-label="Funciones del asistente"><div class="v18-section-kicker"><span class="v18-glint"></span> ${locale==='es'?'DESTACADOS DEL JUEGO':locale==='pt'?'DESTAQUES DO JOGO':'GAME HIGHLIGHTS'} <span class="v18-showcase-count">${String(i+1).padStart(2,'0')} / ${String(homePermanentConfig.length).padStart(2,'0')}</span></div><div class="home-permanent-frame">${homePermanentConfig.map((slide,n)=>`<article class="home-permanent-slide ${i===n?'is-active':''}" aria-hidden="${i!==n}"><div class="home-permanent-art" style="background-image:url('${officialMedia[slide.id]||''}'),url('${homePermanentImages[slide.image]||''}')"></div><div class="home-permanent-shade"></div><div class="home-permanent-copy"><span class="home-permanent-label">${esc(slide.label[locale])}</span><h1>${esc(slide.title[locale])}</h1><p>${esc(slide.description[locale])}</p></div></article>`).join('')}<div class="vi-hero-footer"><a class="home-permanent-cta vi-hero-cta" ${href(homePermanentConfig[i].destination)}>${esc(homePermanentConfig[i].cta[locale])} ↗</a><div class="home-permanent-arrows"><button type="button" data-home-hero-step="-1" aria-label="Anterior"><svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M19 12H5M12 19l-7-7 7-7"/></svg></button><button type="button" data-home-hero-step="1" aria-label="Siguiente"><svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M5 12h14m-7-7 7 7-7 7"/></svg></button></div><div class="home-permanent-dots">${homePermanentConfig.map((v,n)=>`<button type="button" data-home-hero-go="${n}" class="${n===i?'is-active':''}" aria-pressed="${n===i}" aria-label="Ver diapositiva ${n+1}"></button>`).join('')}</div></div></div></section>`}
function refreshPermanentHero(){
 const root=document.querySelector('.home-permanent');if(!root)return;
 const i=(homeSlide+homePermanentConfig.length)%homePermanentConfig.length;
 root.querySelectorAll('.home-permanent-slide').forEach((slide,n)=>{
  const active=n===i;slide.classList.toggle('is-active',active);slide.setAttribute('aria-hidden',String(!active));
 });
 root.querySelectorAll('.home-permanent-dots button').forEach((dot,n)=>{
  const active=n===i;dot.classList.toggle('is-active',active);dot.setAttribute('aria-pressed',String(active));
 });
 const cta=root.querySelector('.vi-hero-cta');
 if(cta){cta.textContent=homePermanentConfig[i].cta[locale]+' ↗';cta.setAttribute('href','#'+homePermanentConfig[i].destination);}
 const counter=root.querySelector('.v18-showcase-count');if(counter)counter.textContent=String(i+1).padStart(2,'0')+' / '+String(homePermanentConfig.length).padStart(2,'0');
}
document.addEventListener('click',e=>{const b=e.target.closest('[data-home-hero-step],[data-home-hero-go]');if(!b)return;e.preventDefault();homeSlide=b.dataset.homeHeroGo!==undefined?Number(b.dataset.homeHeroGo):(homeSlide+Number(b.dataset.homeHeroStep)+homePermanentConfig.length)%homePermanentConfig.length;refreshPermanentHero()});

function renderShowcase(){const slides=homeShowcaseConfig.map(sl=>{const item=sl.recordId?records.find(r=>r.id===sl.recordId):null;return {...sl,title:item?tr(item.title):sl.title?.[locale]||'',description:item?tr(item.summary):sl.summary?.[locale]||'',destination:item?'/ficha/'+item.id:sl.sourceUrl||'/explorar/'+(sl.category||'actualizaciones'),label:sl.label[locale],cta:sl.cta[locale],imageData:homeShowcaseImages[sl.image]||''}});const index=Math.min(homeSlide,slides.length-1);return `<section class="v18-showcase home-visual-band" aria-label="Galería destacada"><div class="v18-section-kicker"><span class="v18-glint"></span> ${locale==='en'?'THE WORLD IN MOTION':locale==='pt'?'O MUNDO EM MOVIMENTO':'DESTACADOS DEL JUEGO'} <span class="v18-showcase-count">${String(index+1).padStart(2,'0')} / ${String(slides.length).padStart(2,'0')}</span></div><div class="v18-showcase-frame">${slides.map((sl,i)=>`<article class="v18-slide ${i===index?'is-active':''}" aria-hidden="${i!==index}"><div class="v18-slide-photo" style="background-image:url('${sl.imageData}')"></div><div class="v18-slide-copy"><span class="v18-slide-tag ${sl.kind==='official'?'is-official':''}">${esc(sl.label)}</span><h3>${esc(sl.title)}</h3><p>${esc(sl.description)}</p>${i===index?`<a class="v18-slide-link" ${sl.destination.startsWith('https://')?`href="${esc(sl.destination)}" target="_blank" rel="noopener noreferrer"`:href(sl.destination)}>${esc(sl.cta)} ↗</a>`:`<span class="v18-slide-link">${esc(sl.cta)} ↗</span>`}</div></article>`).join('')}<div class="v18-carousel-controls"><button type="button" data-slide="-1" aria-label="Imagen anterior">←</button><button type="button" data-slide="1" aria-label="Siguiente imagen">→</button></div></div><div class="v18-slide-dots" role="group" aria-label="Elegir imagen">${slides.map((sl,i)=>`<button type="button" class="${index===i?'is-current':''}" data-slide-go="${i}" aria-label="Ver imagen ${i+1}" aria-pressed="${index===i}"></button>`).join('')}</div><p class="v18-showcase-note">${locale==='es'?'Imágenes del archivo editorial. El material oficial requiere autorización de uso.':locale==='pt'?'Ilustrações conceituais; não são capturas oficiais.':'Concept illustrations, not official screenshots.'}</p></section>`}
let homeSlide=0,homeSlideTimer=null;
function startHomeCarousel(){if(typeof setInterval==='undefined')return;if(homeSlideTimer&&typeof clearInterval!=='undefined')clearInterval(homeSlideTimer);if(decodeURIComponent(location.hash.replace(/^#/,'')||'/').split('?')[0]!=='/')return;homeSlideTimer=setInterval(()=>{if(document.hidden||document.querySelector('.home-permanent:hover')||document.querySelector('.home-permanent:focus-within'))return;homeSlide=(homeSlide+1)%homePermanentConfig.length;refreshPermanentHero()},6800)}
function refreshHomeShowcase(){const el=document.querySelector('.v18-showcase');if(el)el.outerHTML=renderShowcase()}

// V1.40: horizontal swipe for the two editorial carousels. Vertical page scrolling remains native.
(function(){let start=null,blockClickUntil=0;
 document.addEventListener('touchstart',e=>{const frame=e.target.closest('.home-permanent-frame,.v18-showcase-frame');if(!frame||e.touches.length!==1){start=null;return}const t=e.touches[0];start={frame,x:t.clientX,y:t.clientY,time:Date.now()};},{passive:true});
 document.addEventListener('touchend',e=>{if(!start)return;const state=start;start=null;const t=e.changedTouches[0];if(!t)return;const dx=t.clientX-state.x,dy=t.clientY-state.y;if(Math.abs(dx)<48||Math.abs(dx)<Math.abs(dy)*1.4||Date.now()-state.time>1200)return;
  if(state.frame.classList.contains('home-permanent-frame')){homeSlide=(homeSlide+(dx<0?1:-1)+homePermanentConfig.length)%homePermanentConfig.length;refreshPermanentHero()}
  else{homeSlide=(homeSlide+(dx<0?1:-1)+homeShowcaseConfig.length)%homeShowcaseConfig.length;refreshHomeShowcase()}
  blockClickUntil=Date.now()+350;
 },{passive:true});
 document.addEventListener('click',e=>{if(Date.now()<blockClickUntil&&e.target.closest('.home-permanent-frame,.v18-showcase-frame')){e.preventDefault();e.stopImmediatePropagation()}},true);
})();
document.addEventListener('click',e=>{const b=e.target.closest('[data-slide],[data-slide-go]');if(!b)return;e.preventDefault();homeSlide=b.dataset.slideGo!==undefined?Number(b.dataset.slideGo):(homeSlide+Number(b.dataset.slide)+homeShowcaseConfig.length)%homeShowcaseConfig.length;refreshHomeShowcase()});
function homeSearch(){return `<form id="homeSearchForm" class="home-smart-search" role="search"><span aria-hidden="true">⌕</span><input id="homeSearchInput" placeholder="Describí lo que buscás…" aria-label="Buscar en todo el catálogo" value="${esc(searchText)}"><button type="submit">Buscar ↗</button></form><div class="vi-home-search-example">Ej.: personaje masculino de pelo largo</div><div class="search-chips">${['personaje negro','personaje empresario negro','arma con más daño','qué me falta en vehículos'].map(q=>`<button data-home-query="${esc(q)}">${esc(q)}</button>`).join('')}</div><div class="home-inline-results" id="homeInlineResults" aria-live="polite"></div>`}
function showHomeResults(){const box=document.getElementById('homeInlineResults');if(!box)return;const q=searchText.trim();if(!q){box.innerHTML='';return;}const found=detectIntent(q);const rows=found.results.slice(0,6);box.innerHTML=`<div class="home-result-heading"><strong>${rows.length?`Resultados para «${esc(q)}»`:`No encontramos coincidencias para «${esc(q)}»`}</strong><span>${rows.length?`${rows.length} coincidencia(s) visibles`:'Probá con otra descripción'}</span></div>${found.explanation?`<p class="home-result-note">${esc(found.explanation)}</p>`:''}${rows.map(i=>`<a class="home-result-card" ${href('/ficha/'+i.id)}><span>${esc(tr(i.title))}</span><small>${esc(tr(cat(i.category).label))}</small><b>Ver ficha ↗</b></a>`).join('')}${found.results.length>6?`<a class="home-result-more" ${href('/buscar')}>Ver más resultados ↗</a>`:''}`}

function lastOpened(){const recent=store('recent').map(id=>records.find(x=>x.id===id)).filter(Boolean).slice(0,2);return `<div class="section-head"><h2>Seguir explorando</h2><a ${href('/partida')}>Mi partida →</a></div>${recent.length?`<div class="item-stack">${recent.map(resultCard).join('')}</div>`:`<p class="muted small">Abrí una ficha y te aparecerá acá para retomarla rápidamente.</p>`}`}
function filterGuideGroups(){const groups=SEARCH_FILTERS[filterGuideCategory]||{};
 return Object.entries(groups).map(([field,values])=>`<details class="filter-guide-group"><summary>${esc(field.replaceAll('_',' '))} · ${Object.keys(values).length}</summary><div class="filter-guide-options">${Object.entries(values).map(([value,aliases])=>`<label class="multi-facet ${multiFilters.some(f=>f.field===field&&f.value===value)?'is-active':''}" title="Sinónimos: ${esc(aliases.join(', '))}"><input type="checkbox" data-facet-field="${esc(field)}" data-facet-value="${esc(value)}" ${multiFilters.some(f=>f.field===field&&f.value===value)?'checked':''}>${esc(value.replaceAll('_',' '))}</label>`).join('')}</div></details>`).join('');
}
function dynamicFilterGuide(){const vals=new Map();for(const i of records.filter(x=>x.category===filterGuideCategory)){const walk=(obj,path=[])=>{if(!obj||typeof obj!=='object'||Array.isArray(obj))return;for(const[k,v]of Object.entries(obj))if(v&&typeof v==='object'&&!Array.isArray(v))walk(v,[...path,k]);else for(const val of Array.isArray(v)?v:[v]){const name=[...path,k].join('.');if(!vals.has(name))vals.set(name,new Set());vals.get(name).add(String(val))}};walk(i.attributes)}
 if(!vals.size)return '';return `<details class="filter-guide-group"><summary>✨ Atributos automáticos · ${vals.size}</summary><div class="filter-guide-options">${[...vals.entries()].flatMap(([key,values])=>[...values].slice(0,15).map(value=>`<label class="multi-facet ${multiFilters.some(f=>f.field==='atributo:'+key&&f.value===value)?'is-active':''}"><input type="checkbox" data-facet-field="${esc('atributo:'+key)}" data-facet-value="${esc(value)}" ${multiFilters.some(f=>f.field==='atributo:'+key&&f.value===value)?'checked':''}>${esc(key.replaceAll('.',' ')+': '+value)}</label>`)).join('')}</div></details>`;}
function filterGuide(){return `<details class="search-filter-guide"><summary>🧩 Lista de filtros avanzados</summary><div class="filter-guide-body"><label for="filterGuideCategory">Categoría</label><select id="filterGuideCategory">${categories.map(x=>`<option value="${esc(x.id)}" ${x.id===filterGuideCategory?'selected':''}>${esc(tr(x.label))}</option>`).join('')}</select><p class="muted small">Elegí varios filtros: entre grupos se combinan; dentro de un grupo alcanza con uno. Los sinónimos siguen activos en las búsquedas escritas.</p><div id="filterGuideGroups">${filterGuideGroups()}${dynamicFilterGuide()}</div></div></details>${multiFilters.length?`<div class="multi-filter-action"><b>${multiFilters.length} filtros seleccionados</b><span>Todos los grupos deben coincidir.</span><button data-multi-clear>Limpiar</button></div>`:``}`;}
