 if(!mapAdd){if(mapActive){mapActive=null;mapUpdate()}return}const p=pointFromTouch(t),fit=viMapFit(el),scale=fit*mapZoom,cx=(el.clientWidth-MAP_WIDTH*fit)/2,cy=(el.clientHeight-MAP_HEIGHT*fit)/2;
