 if(a==='search-jump'){const el=document.getElementById('mapSearchText');el?.scrollIntoView({behavior:'smooth',block:'center'});el?.focus({preventScroll:true});return;}if(a==='clear')mapCategories=[];else if(a==='all')mapCategories=mapCategories.length===mapFilterCategories.length?[]:mapFilterCategories.map(x=>x.id);else if(a==='focus'){mapFocusPin(v);return}else if(a==='focus-custom'){mapMarkerManagerOpen=true;mapFocusPin(v);document.getElementById('mapCanvas')?.scrollIntoView({behavior:'smooth',block:'center'});return}else if(a==='pin'){mapActive=v;mapDraft=null;}else if(a==='add'){mapAdd=!mapAdd;mapDraft=null;mapActive=null;mobileMapFiltersOpen=false;}else if(a==='abort-marker'){mapAdd=false;mapDraft=null;mapActive=null;mobileMapFiltersOpen=false;}else if(a==='close')mapActive=null;else if(a==='cancel'){mapDraft=null;mapAdd=false;mobileMapFiltersOpen=false;}else if(a==='reset'){mapZoom=1;mapDX=0;mapDY=0;}else if(a==='zoom'){mapChangeZoom(Number(v),document.getElementById('mapCanvas').clientWidth/2,document.getElementById('mapCanvas').clientHeight/2);return}
 else if(a==='delete'){const owned=mapCustom(),target=owned.find(p=>p.id===v&&p.kind==='personal');if(!target)return;const prompt=tr({es:`¿Eliminar el marcador «${target.title}»? No se puede deshacer.`,en:`Delete marker “${target.title}”? This cannot be undone.`,pt:`Excluir o marcador “${target.title}”? Esta ação não pode ser desfeita.`});if(!window.confirm(prompt))return;try{localStorage.setItem(MAP_LOCAL_KEY,JSON.stringify(owned.filter(p=>p.id!==v)));if(mapActive===v)mapActive=null;mapMarkerManagerOpen=true;}catch(error){console.error('Cannot delete personal marker',error);window.alert(tr({es:'No se pudo eliminar el marcador. Probá nuevamente.',en:'Could not delete the marker. Please try again.',pt:'Não foi possível excluir o marcador. Tente novamente.'}));return;}}
