document.addEventListener('click',e=>{const s=e.target.closest('summary');const d=s?.closest('details[data-map-group]');if(!d)return;if(d.open)mapOpenFilterGroups.delete(d.dataset.mapGroup);else mapOpenFilterGroups.add(d.dataset.mapGroup);});
document.addEventListener('change',e=>{if(e.target.matches('[data-map-cat]')){const cat=e.target.dataset.mapCat;mapCategories=e.target.checked?[...new Set([...mapCategories,cat])]:mapCategories.filter(x=>x!==cat);mapUpdate()}else if(e.target.matches('[data-map-missing]')){mapMissing=e.target.checked;if(mapMissing)mapCompleted=false;mapUpdate()}else if(e.target.matches('[data-map-completed]')){mapCompleted=e.target.checked;if(mapCompleted)mapMissing=false;mapUpdate()}else if(e.target.matches('[data-map-favorites]')){mapFavOnly=e.target.checked;mapUpdate()}});
document.addEventListener('input',e=>{if(e.target.id==='mapSearchText'){mapQuery=e.target.value;const at=e.target.selectionStart;mapUpdate();const input=document.getElementById('mapSearchText');input?.focus();input?.setSelectionRange(at,at)}});

document.addEventListener('error',e=>{if(e.target?.classList?.contains('atlas-popup-photo')&&e.target.dataset.fallback){e.target.src=e.target.dataset.fallback;e.target.dataset.fallback='';}},true);
