document.addEventListener('submit',e=>{if(e.target.id==='homeSearchForm'){e.preventDefault();searchText=document.getElementById('homeSearchInput')?.value||'';showHomeResults();document.getElementById('homeInlineResults')?.scrollIntoView({block:'nearest',behavior:'smooth'});return}if(e.target.id==='headerSearchForm'){e.preventDefault();if(location.hash==='#/buscar'){document.getElementById('searchInput')?.focus();showResults();updateHeaderSuggestions(false)}else{location.hash='#/buscar';render();document.getElementById('searchInput')?.focus();}}});
// V1.42: stable bridge for signed catalog updates. All screens derive from shared `records`.
window.viApplySignedCatalog=function(items){
 const existing=new Map(records.map(r=>[r.id,r]));
 let added=0,changed=0;
 for(const it of items){
  const old=existing.get(it.id);
  if(old){
   // Preserve curated facts, local media and game-specific metadata unless update explicitly carries verified fields.
   existing.set(it.id,{...old,...it,image:(it.image?.data||it.image?.remote)?it.image:old.image||{},facets:{...(old.facets||{}),...(it.facets||{})},tags:it.tags?.length?it.tags:(old.tags||[]),trackable:it.trackable===undefined?old.trackable:it.trackable,mapPoint:it.mapPoint||old.mapPoint,publishedAt:it.publishedAt||old.publishedAt,facts:it.facts?.length?it.facts:(old.facts||[]),gallery:Array.isArray(it.gallery)?it.gallery:old.gallery}); changed++;
  }else{existing.set(it.id,{...it,image:(it.image?.data||it.image?.remote)?it.image:undefined});added++}
 }
 records.splice(0,records.length,...existing.values());
 const y=window.scrollY;
 render();requestAnimationFrame(()=>window.scrollTo(0,y));
 document.dispatchEvent(new CustomEvent('vi:catalog-refresh',{detail:{added,changed,total:records.length}}));
 return {added,changed,total:records.length};
};
window.viUpdateSignedImages=function(images){let changed=false;for(const {id,url} of images){const r=records.find(x=>x.id===id);if(r&&url?.startsWith('blob:')){r.image={...(r.image||{}),data:url};changed=true}}if(changed){const y=scrollY;render();requestAnimationFrame(()=>scrollTo(0,y))}};
window.viCatalogSnapshot=()=>({records:records.map(x=>({id:x.id,category:x.category,title:x.title,mapPoint:x.mapPoint||null})),categories:categories.map(x=>x.id),mapVersion:MAP_VERSION});
window.viRouteContext=()=>({locale,mapVersion:MAP_VERSION,pins:allMapPins().map(p=>({id:p.id,title:p.title,note:p.note||'',x:p.x,y:p.y,kind:p.kind,itemId:p.itemId||null})),done:store('done')});
window.viRouteFocusPin=(id)=>{mapFocusPin(id);document.getElementById('mapCanvas')?.scrollIntoView({behavior:'smooth',block:'center'});};
window.viCatalogRouteItems=()=>records.filter(r=>r.mapPoint?.mapVersion===MAP_VERSION&&r.status==='verified').map(r=>r.id);
window.viRefreshApp=()=>render();
window.viRefreshComparison=()=>{
 const previous=document.querySelector('.vi-compare-page');
 if(!previous||!location.hash.startsWith('#/comparar'))return false;
 const markup=window.viDetailEnhancements?.comparePage(records,locale);
 if(typeof markup!=='string')return false;
 const template=document.createElement('template');
 template.innerHTML=markup.trim();
 const updated=template.content.firstElementChild;
 const controls=previous.querySelector('.vi-compare-controls');
 const nextControls=updated?.querySelector('.vi-compare-controls');
 if(!updated||!controls||!nextControls)return false;
 // Preserve the original controls and the page height. Replacing the whole
 // section used to blur the active select and shrink the page, clamping scrollY.
 const oldY=window.scrollY;
 const before=previous.getBoundingClientRect();
 const minHeight=Math.max(before.height,oldY+window.innerHeight-(oldY+before.top)+48);
 previous.style.minHeight=Math.ceil(minHeight)+'px';
 const oldSelects=controls.querySelectorAll('select');
 const newSelects=nextControls.querySelectorAll('select');
 if(oldSelects.length!==newSelects.length)return false;
 oldSelects.forEach((select,i)=>{
  const desired=newSelects[i];
  if(select.innerHTML!==desired.innerHTML)select.innerHTML=desired.innerHTML;
  if(select.value!==desired.value)select.value=desired.value;
 });
 const replacement=document.createDocumentFragment();
 for(let node=nextControls.nextSibling;node;node=node.nextSibling)replacement.appendChild(node.cloneNode(true));
 while(controls.nextSibling)controls.nextSibling.remove();
 previous.appendChild(replacement);
 // No navigation, lost select focus, or full-screen rerender.
 if(window.scrollY!==oldY)window.scrollTo({top:oldY,behavior:'instant'});
 return true;
};
window.viApplySignedRankings=(next)=>{if(!next||!Array.isArray(next.donations)||!Array.isArray(next.speedruns))return;
 publicRankings.speedruns.splice(0,publicRankings.speedruns.length,...next.speedruns);
 publicRankings.donations.splice(0,publicRankings.donations.length,...next.donations);
 const y=scrollY;render();requestAnimationFrame(()=>scrollTo(0,y));
};


// Comparisons are an in-page workspace. Intercept hash links before the browser
// performs native anchor scrolling, then focus the controls after rendering.
document.addEventListener('click',event=>{
 const link=event.target.closest?.('a[href^="#/comparar"]');
 if(!link||event.defaultPrevented||event.button!==0||event.metaKey||event.ctrlKey||event.shiftKey||event.altKey)return;
 const href=link.getAttribute('href');
 if(!href)return;
 event.preventDefault();
 const wasCompare=location.hash.startsWith('#/comparar');
 const oldY=window.scrollY;
 history.pushState(history.state,'',href);
 if(wasCompare&&window.viRefreshComparison?.())return;
 render();
 requestAnimationFrame(()=>{
  const anchor=document.querySelector('.vi-compare-controls');
  if(anchor){
   const y=anchor.getBoundingClientRect().top+window.scrollY-24;
   window.scrollTo({top:Math.max(0,y),behavior:'instant'});
  }else window.scrollTo({top:oldY,behavior:'instant'});
 });
},true);
window.addEventListener('hashchange',()=>{
 const comparing=location.hash.startsWith('#/comparar');
 if(!comparing)window.scrollTo(0,0);
 const previousY=window.scrollY;
 render();
 if(comparing)requestAnimationFrame(()=>{
  const controls=document.querySelector('.vi-compare-controls');
  if(controls&&previousY===0)controls.scrollIntoView({block:'start',behavior:'instant'});
  else window.scrollTo({top:previousY,behavior:'instant'});
 });
 const route=decodeURIComponent(location.hash.replace(/^#/,'')||'/').split('?')[0];
 if(route==='/partida'&&/[?&]estado=(favoritos|completados|pendientes)/.test(location.hash)){
  requestAnimationFrame(()=>document.getElementById('playthroughFilteredList')?.scrollIntoView({behavior:'smooth',block:'start'}));
 }
});
// V178: local, deterministic fallback whenever a verified remote illustration fails.
// Works for both desktop and mobile cards without retry loops or external services.
document.addEventListener('error',event=>{
 const image=event.target;
 if(image?.tagName!=='IMG')return;
 const fallback=image.getAttribute('data-vi-image-fallback');
 if(!fallback)return;
 image.removeAttribute('data-vi-image-fallback');
 if(image.getAttribute('src')!==fallback)image.src=fallback;
},true);
render();

